import java.io.*;

public class Main {
    public static void main(String[] args) throws Exception {
        try (BufferedReader br = new BufferedReader(new InputStreamReader(System.in))) {
            long n = Long.parseLong(br.readLine());
            System.out.println(computeOnes(n));
        }
    }

    private static int digitCount(long n) {
        return (int) Math.log10(n) + 1;
    }

    private static long buildOnes(int len) {
        long result = 1;
        int i = len;
        while (--i > 0) {
            result = result * 10 + 1;
        }
        return result;
    }

    private static long computeOnes(long n) {
        if (n <= 6) return n;
        int d = digitCount(n);
        long base = buildOnes(d);
        long step = base;
        long diff = n;
        int cnt = 0;
        while (base < n) {
            cnt++;
            diff = n - base;
            base += step;
        }
        long ans;
        if (cnt > 0) {
            ans = Math.min(cnt * d + computeOnes(diff), (cnt + 1) * d + computeOnes(base - n));
        } else {
            ans = (cnt + 1) * d + computeOnes(base - n);
        }
        long nextBase = buildOnes(d + 1);
        if (nextBase - n < n) {
            ans = Math.min(ans, d + 1 + computeOnes(nextBase - n));
        }
        return ans;
    }
}
